class Node(Taggable, Labelable, SummaryMixin, Navigatable):
    PLURAL = 'Nodes'
    def __init__(self, name, provider, collection=None, appliance=None):
        self.name = name
        self.provider = provider
        if not collection:
            collection = NodeCollection(appliance=appliance)
        self.collection = collection
        Navigatable.__init__(self, appliance=appliance)
    def load_details(self, refresh=False):
        navigate_to(self, 'Details')
        if refresh:
            tb.refresh()
    def get_detail(self, *ident):
        """ Gets details from the details infoblock
        Args:
            *ident: Table name and Key name, e.g. "Relationships", "Images"
        Returns: A string representing the contents of the summary's value.
        """
        self.load_details()
        return InfoBlock.text(*ident)
    @classmethod
    def get_random_instances(cls, provider, count=1, appliance=None):
        """Generating random instances."""
        node_list = provider.mgmt.list_node()
        random.shuffle(node_list)
        return [cls(obj.name, provider, appliance=appliance)
                for obj in itertools.islice(node_list, count)]
