								  "Medium", "Large", "X-Large", "XX-Large" };

		public FontUnit (FontSize type)
		{
			int t = (int) type;

			if (t < 0 || t > (int)FontSize.XXLarge)
				throw new ArgumentOutOfRangeException ("type");

			this.type = type;
			if (type == FontSize.AsUnit)
				unit = new Unit (10, UnitType.Point);
			else
				unit = Unit.Empty;
		}
