                    if (_escapeCount == 0)
                    {
                        ClearMask();
                    }
                }
                _minimumContext = _maximumContext;
                _numberStatistics = _minimumContext.NumberStatistics;
                _coder.RangeDecoderNormalize(source);
            }
            StopDecoding:
