				_orderPreviewComponent.Context = _dryRunMergedOrder;
				_attachmentSummaryComponent.Attachments = _dryRunMergedOrder.Attachments;
			}
			_extensionPageContext.NotifyDryRunMergedOrderChanged();
		}
