    public static void distributeKinah(Player player, long kinah) {
        PlayerGroup group = player.getPlayerGroup2();
        if (group != null) {
            group.onEvent(new TeamKinahDistributionEvent<PlayerGroup>(group, player, kinah));
        }
    }
