                                        break;
                                    case 5:
                                        w.WeaponAttributes.HitLeechHits += attributes.WeaponHitLifeLeech;
                                        break;
                                }
                            }
                            #endregion
                            int hue = w.GetElementalDamageHue();
                            if (hue > 0)
                                w.Hue = hue;
                        }
                        #region Mondain's Legacy
                        else if (item is BaseShield)
                        {
                            BaseShield shield = (BaseShield)item;
                            shield.Resource = resource;
                            switch (resource)
